// Creates the app/, components/ and lib/ folders before "next build".
// Needed because the GitHub web upload skipped those folders. It always writes the bundled version,
// so this file is the source of truth for the dashboard code.
import { mkdirSync, writeFileSync } from 'node:fs';
import { dirname } from 'node:path';
const FILES = {"app/globals.css":"","app/layout.tsx":"","app/login/page.tsx":"","app/page.tsx":"","app/upload/page.tsx":"","app/users/page.tsx":"","components/Charts.tsx":"","components/Ledger.tsx":"","components/Shell.tsx":"","lib/api.ts":"","lib/calc.ts":"","lib/export.ts":"","lib/live.ts":"","lib/mapping.ts":""};
let made = 0;
for (const [p, b64] of Object.entries(FILES)) {
  mkdirSync(dirname(p), { recursive: true });
  writeFileSync(p, Buffer.from(b64, 'base64'));
  made++;
}
console.log('unpack-source: created ' + made + ' of ' + Object.keys(FILES).length + ' source files');
